} from '../../api/suites';
import { useAsyncData } from '../../hooks/useAsyncData';
import {
  AXIS_TICK,
  CHART_COLORS,
  GRID_PROPS,
  severityColor,
  TOOLTIP_STYLE,
} from '../charts/chartTheme';
