export type ConfirmDeleteOptions = {
  /** Entity name — used in the default title and success message. */
  label: string;
  /** Optional explanatory body under the title. */
  content?: ReactNode;
  /** Confirm button text. Default `'Delete'`. */
  okText?: string;
  /** Toast on success. Default `` `${label} deleted` ``. */
  successMessage?: string;
  /** Prefix for the error toast. Default `'Delete failed'`. */
  errorPrefix?: string;
  /** The destructive call. */
  onDelete: () => Promise<void>;
  /** Ran after a successful delete (e.g. refetch). */
  onDone?: () => void;
};

/**
 * The danger-delete confirm modal shared by the connection / suite / check delete sites:
 * `modal.confirm({ okType: 'danger', … })` → success toast + `onDone`.
 */
export function useConfirmDelete() {
  const { message } = App.useApp();
  const modal = useAppModal();

  return (opts: ConfirmDeleteOptions) => {
    const { label, content, okText = 'Delete', onDelete, onDone } = opts;
    const successMessage = opts.successMessage ?? `${label} deleted`;
    const errorPrefix = opts.errorPrefix ?? 'Delete failed';

    modal.confirm({
      title: `Delete “${label}”?`,
      content,
      okText,
      okType: 'danger',
      onOk: async () => {
        try {
          await onDelete();
          message.success(successMessage);
          onDone?.();
        } catch (err) {
          message.error(`${errorPrefix}: ${errorMessage(err)}`);
          throw err; // keep the confirm modal open on failure
        }
      },
    });
  };
}

import axios from 'axios';

import { errorMessage } from './errors';

/**
 * Map a backend 422 onto a form field, so a refusal lands where the author can act on it instead
 * of in a toast that dismisses itself.
 */
export interface ApiFieldError {
  code: string;
  message: string;
  detail: Record<string, unknown>;
}

/** The `{error: {code, message, detail}}` envelope, or `undefined` if this isn't
 *  one — a network failure or a non-DataQError response. */
export function apiFieldError(err: unknown): ApiFieldError | undefined {
  if (!axios.isAxiosError(err)) return undefined;
  const envelope = (err.response?.data as { error?: Partial<ApiFieldError> } | undefined)?.error;
  if (typeof envelope?.code !== 'string') return undefined;
  return {
    code: envelope.code,
    // The interceptor has already swapped the envelope message onto
    // `error.message`; prefer the envelope's own so this doesn't depend on that.
    message: typeof envelope.message === 'string' ? envelope.message : errorMessage(err),
    detail: (envelope.detail as Record<string, unknown>) ?? {},
  };
}

/** A `detail` value that is a list of names (e.g. the conflicting checks), or
 *  `[]` — so a caller can name the obstacle rather than say "something conflicts". */
export function detailNames(detail: Record<string, unknown>, key: string): string[] {
  const value = detail[key];
  return Array.isArray(value) ? value.filter((v): v is string => typeof v === 'string') : [];
}
