import type { ReactNode } from 'react';
import { Alert, Spin } from 'antd';

import type { AsyncState } from '../hooks/useAsyncData';
import { PageError } from './feedback/PageError';

/**
 * The `if loading → Spin / if error → render / else render-data` ladder that every `useAsyncData`
 * consumer hand-rolled.
 */
export function AsyncBody<T>({
  state,
  loadingText,
  errorTitle,
  page = false,
  onRetry,
  children,
}: {
  state: AsyncState<T>;
  /** Caption for the default spinner. */
  loadingText?: string;
  errorTitle: string;
  /** Whole-page fetch → dedicated error page instead of the inline Alert. */
  page?: boolean;
  /** In-place retry for the page rendering (usually `reload`). */
  onRetry?: () => void;
  children: (data: T) => ReactNode;
}): ReactNode {
  if (state.status === 'loading') return <Spin description={loadingText} />;
  if (state.status === 'error') {
    if (page) {
      return (
        <PageError
          error={state.error}
          kind={state.kind}
          httpStatus={state.httpStatus}
          requestId={state.requestId}
          onRetry={onRetry}
        />
      );

import { App, type ModalFuncProps } from 'antd';
import { useMemo } from 'react';

import { MODAL_TRANSITION } from '../components/shared/Modal';

/** `App.useApp().modal`, with every dialog opening with the app's fade instead of a zoom
 *  (#2466). ESLint rejects taking `modal` from `App.useApp()` directly. */
export function useAppModal() {
  const { modal } = App.useApp();
  return useMemo(() => {
    const withFade = (config: ModalFuncProps): ModalFuncProps => ({
      ...config,
      transitionName: config.transitionName ?? MODAL_TRANSITION,
    });
    return {
      confirm: (config: ModalFuncProps) => modal.confirm(withFade(config)),
      info: (config: ModalFuncProps) => modal.info(withFade(config)),
      success: (config: ModalFuncProps) => modal.success(withFade(config)),
      error: (config: ModalFuncProps) => modal.error(withFade(config)),
      warning: (config: ModalFuncProps) => modal.warning(withFade(config)),
    };
  }, [modal]);
}
import { Modal as AntModal, type ModalProps } from 'antd';

/** The transition every dialog opens with (#2466). antd's default zooms the dialog in from
 *  a small scale, and a Select inside it sizes its dropdown from the trigger's on-screen
 *  width when it opens: clicked during the zoom, the dropdown stays a sliver of the field.
 *  A fade never scales, so the measurement is always the real width. */
export const MODAL_TRANSITION = 'ant-fade';

/** antd's Modal, opening with a fade instead of a zoom. Use it for every dialog; ESLint
 *  rejects importing `Modal` from antd directly. For `confirm()`-style dialogs, use
 *  `useAppModal`. */
export function Modal(props: ModalProps) {
  return <AntModal {...props} transitionName={props.transitionName ?? MODAL_TRANSITION} />;
}

