      .getByRole('dialog', { name: /^Delete/ })
      .getByRole('button', { name: 'Delete' })
      .click();
    await expect(page.locator('tr').filter({ hasText: name })).toHaveCount(0);
  });

  test('a refused delete names the check that still attaches the entry', async ({
    page,
