    const entry = await addEntry(request, `e2e attached ${stamp}`);
    const suite = await suiteId(request);
    const check = await addPerPeriodCheck(request, suite, `e2e per day ${stamp}`, [entry]);
    try {
      await page.goto('/admin/calendar');
