      await page
        .getByRole('dialog', { name: /^Delete/ })
        .getByRole('button', { name: 'Delete' })
        .click();
      const blocked = page.getByTestId('calendar-delete-blocked');
      await expect(blocked).toContainText('is still attached to 1 check');
