import { expect, type Page } from '@playwright/test';

/** Wait until the page has stopped loading. A route's landmark can be visible while a table
 * inside it is still behind its `loading` Spin, so the rows a scan should judge are not in the
 * DOM yet and the scan passes vacuously. Also lets mount transitions finish, which otherwise
 * get sampled mid-colour. */
export async function settle(page: Page): Promise<void> {
  await expect(page.locator('.ant-spin-spinning, .ant-skeleton-active')).toHaveCount(0);
  await page.evaluate(() =>
    Promise.all(
      document
        .getAnimations()
        .filter((a) => a.effect?.getComputedTiming().iterations !== Infinity)
        .map((a) => a.finished.catch(() => undefined)),
    ),
  );
}

const DECLARED_FILL = SEVERITY_SCALE.warning;
const DETECTED_STROKE = CHART_COLORS.axis;

function SourceDot(props: unknown) {
  const { cx, cy, payload, index } = props as {
    cx?: number;
    cy?: number;
    index: number;
    payload: { backfilled: boolean };
  };
  if (cx === undefined || cy === undefined) return <g key={index} />;
  // Seeded points are hollow, observed ones filled: readable without color.
  return payload.backfilled ? (
    <circle
      key={index}
      cx={cx}
      cy={cy}
      r={2.5}
      fill="none"
      stroke={CHART_COLORS.axis}
      strokeWidth={1}
    />
  ) : (
    <circle key={index} cx={cx} cy={cy} r={2.5} fill={CHART_COLORS.primary} />
  );
}

/**
 * The stored periods with, for each period a run judged, the band it was scored against and,
 * where the yearly comparison applied, the expected value; attached calendar entries shaded and
 * detected periods outlined.
 */
export function PeriodBaselineChart({
  rows,
  k,
  declared,
  detected,
  formatDay,
}: {
  rows: PeriodRow[];
  k: number;
  declared: SeasonalPeriod[];
  detected: DetectedPeriod[];
  formatDay: (day: string) => string;
}) {
  const days = rows.map((r) => r.day);
  const data = rows.map((r) => {
    const j = r.judged;
    const band =
      j && j.banded && j.mean !== null && j.stddev !== null
        ? [j.mean - k * j.stddev, j.mean + k * j.stddev]
        : null;
    return { day: r.day, value: r.value, backfilled: r.backfilled, expected: j?.expected, band };
  });
  const first = days[0];
  const last = days[days.length - 1];
  const declaredAreas = first
    ? declared.flatMap((p) =>
        occurrencesBetween(p, first, last).flatMap((o) => {
          const snapped = snapToDays(days, o);
          return snapped ? [{ key: `${p.id}${o.start}`, name: p.name, ...snapped }] : [];
        }),
      )
    : [];
  const detectedAreas = detected.flatMap((d) =>
    d.occurrences.flatMap((o) => {
      const snapped = snapToDays(days, o);
      return snapped ? [{ key: `${d.start}${o.start}`, ...snapped }] : [];
    }),
  );

  return (
    <ResponsiveChart
      height={180}
      isEmpty={data.length === 0}
      emptyText="No baseline observations recorded yet"
    >
      <ComposedChart data={data} margin={{ top: 14, right: 12, left: -16, bottom: 0 }}>
        <CartesianGrid {...GRID_PROPS} vertical={false} />
        <XAxis
          dataKey="day"
          tick={AXIS_TICK}
          tickLine={false}
          minTickGap={24}
          tickFormatter={formatDay}
        />
        <YAxis tick={AXIS_TICK} tickLine={false} width={40} />
        <Tooltip contentStyle={TOOLTIP_STYLE} labelFormatter={(d) => formatDay(String(d))} />
        {declaredAreas.map((a) => (
          <ReferenceArea
            key={a.key}
            x1={a.x1}
            x2={a.x2}
            fill={DECLARED_FILL}
            fillOpacity={0.12}
            label={{ value: a.name, position: 'insideTop', fontSize: 10 }}
          />
        ))}
        {detectedAreas.map((a) => (
          <ReferenceArea
            key={a.key}
            x1={a.x1}
            x2={a.x2}
            fill="none"
            stroke={DETECTED_STROKE}
            strokeDasharray="4 3"
          />
        ))}
        <Area
          dataKey="band"
          name="Scored against"
          stroke="none"
          fill={CHART_COLORS.primary}
          fillOpacity={0.12}
          connectNulls={false}
          isAnimationActive={false}
        />
        <Line
          dataKey="expected"
          name="Expected"
          stroke={CHART_COLORS.axis}
          strokeDasharray="6 3"
          strokeWidth={1.5}
          dot={false}
          connectNulls={false}
          isAnimationActive={false}
        />
        <Line
          type="monotone"
          dataKey="value"
          name="Value"
          stroke={CHART_COLORS.primary}
          strokeWidth={1.5}
          dot={SourceDot}
          isAnimationActive={false}
        />
      </ComposedChart>
    </ResponsiveChart>
  );
}

