start = s.index("/**\n * The stored periods with, for each period a run judged")
end = s.index("function spanText(")
chart = '''/**
 * The stored periods with, for each period a run judged, the band it was scored against and,
 * where the yearly comparison applied, the expected value; attached calendar entries shaded and
 * detected periods outlined, each over the dates it covers.
 */
export function PeriodBaselineChart({
  rows,
  k,
  declared,
  detected,
  formatDay,
}: {
  rows: PeriodRow[];
  k: number;
  declared: SeasonalPeriod[];
  detected: DetectedPeriod[];
  formatDay: (day: string) => string;
}) {
  const data = rows.map((r) => {
    const j = r.judged;
    const banded = j !== null && j.banded && j.mean !== null && j.stddev !== null;
    return {
      x: dayMs(r.day),
      value: r.value,
      backfilled: r.backfilled,
      expected: j?.expected ?? null,
      band: banded ? [j.mean! - k * j.stddev!, j.mean! + k * j.stddev!] : null,
      // The centre with a whisker of k spreads: visible even for a period with no judged
      // neighbour, where the shaded band has nothing to join.
      centre: banded ? j.mean : null,
      spread: banded ? k * j.stddev! : null,
    };
  });
  const first = rows[0]?.day;
  const last = rows[rows.length - 1]?.day;
  const declaredAreas = first ? declaredAreasBetween(declared, first, last) : [];
  const detectedAreas = detected.flatMap((d) =>
    d.occurrences.map((o) => ({ key: `${d.start}${o.start}`, ...spanMs(o) })),
  );
  const domain: [number, number] = first
    ? [dayMs(first), dayMs(last) + DAY_MS]
    : [0, DAY_MS];
  const tick = (ms: number) => formatDay(new Date(ms).toISOString().slice(0, 10));

  return (
    <ResponsiveChart
      height={180}
      isEmpty={data.length === 0}
      emptyText="No baseline observations recorded yet"
    >
      <ComposedChart data={data} margin={{ top: 14, right: 12, left: -16, bottom: 0 }}>
        <CartesianGrid {...GRID_PROPS} vertical={false} />
        <XAxis
          dataKey="x"
          type="number"
          scale="time"
          domain={domain}
          tick={AXIS_TICK}
          tickLine={false}
          minTickGap={24}
          tickFormatter={tick}
        />
        <YAxis tick={AXIS_TICK} tickLine={false} width={40} />
        <Tooltip contentStyle={TOOLTIP_STYLE} labelFormatter={(ms) => tick(Number(ms))} />
        {declaredAreas.map((a) => (
          <ReferenceArea
            key={a.key}
            x1={a.x1}
            x2={a.x2}
            ifOverflow="hidden"
            fill={DECLARED_FILL}
            fillOpacity={0.12}
            label={{ value: a.name, position: 'insideTop', fontSize: 10 }}
          />
        ))}
        {detectedAreas.map((a) => (
          <ReferenceArea
            key={a.key}
            x1={a.x1}
            x2={a.x2}
            ifOverflow="hidden"
            fill="none"
            stroke={DETECTED_STROKE}
            strokeDasharray="4 3"
          />
        ))}
        <Area
          dataKey="band"
          name="Scored against"
          stroke="none"
          fill={CHART_COLORS.primary}
          fillOpacity={0.12}
          connectNulls={false}
          isAnimationActive={false}
        />
        <Scatter dataKey="centre" name="Scored-against centre" fill="none" isAnimationActive={false}>
          <ErrorBar dataKey="spread" direction="y" stroke={CHART_COLORS.primary} width={4} />
        </Scatter>
        <Line
          dataKey="expected"
          name="Expected"
          stroke={CHART_COLORS.axis}
          strokeDasharray="6 3"
          strokeWidth={1.5}
          dot={{ r: 2, fill: CHART_COLORS.axis }}
          connectNulls={false}
          isAnimationActive={false}
        />
        <Line
          type="monotone"
          dataKey="value"
          name="Value"
          stroke={CHART_COLORS.primary}
          strokeWidth={1.5}
          dot={SourceDot}
          isAnimationActive={false}
        />
      </ComposedChart>
    </ResponsiveChart>
  );
}

'''
s = s[:start] + chart + s[end:]
s = s.replace(
    """  CartesianGrid,
  ComposedChart,
  Line,
  ReferenceArea,""",
    """  CartesianGrid,
  ComposedChart,
  ErrorBar,
  Line,
  ReferenceArea,
  Scatter,""",
)
s = s.replace(
    """  occurrencesBetween,
  promoteDetectedPeriod,""",
    """  promoteDetectedPeriod,""",
)
s = s.replace(
    "import { snapToDays } from './seasonalTrendData';",
    "import { DAY_MS, dayMs, declaredAreasBetween, spanMs } from './seasonalTrendData';",
)
p.write_text(s)

p = pathlib.Path("frontend/src/components/checks/seasonalTrendData.ts")
s = p.read_text()
start = s.index("/** `[start, end]` snapped to")
s = s[:start] + '''export const DAY_MS = 24 * 60 * 60 * 1000;

/** A `YYYY-MM-DD` day as epoch milliseconds at UTC midnight. */
export function dayMs(day: string): number {
  return Date.parse(`${day}T00:00:00Z`);
}

/** An inclusive day range as the span it covers on a time axis: its first day's start to the
 *  end of its last day. */
export function spanMs(range: { start: string; end: string }): { x1: number; x2: number } {
  return { x1: dayMs(range.start), x2: dayMs(range.end) + DAY_MS };
}

/** Each occurrence of the attached entries that touches `[first, last]`, named. */
export function declaredAreasBetween(
  declared: SeasonalPeriod[],
  first: string,
  last: string,
): { key: string; name: string; x1: number; x2: number }[] {
  return declared.flatMap((p) =>
    occurrencesBetween(p, first, last).map((o) => ({
      key: `${p.id}${o.start}`,
      name: p.name,
      ...spanMs(o),
    })),
  );
}
'''
