}

/** `GET /admin/telemetry`. `enabled` is the effective state: the stored opt-in AND a sink the
 *  operator configured. With `sink = off` the opt-in is stored but sends nothing. */
export interface TelemetrySettings {
  enabled: boolean;
  stored: boolean;
  sink: 'off' | 'file' | 'otlp';
